mapper.select:
SELECT id, tool_invocation_id, run_id, request_id, session_id, tool_call_id, status, error_msg,
       skill_name, script_name, runtime, success, exit_code, stdout, stderr, summary, created_at, updated_at
FROM ai_agent_tool_output_script_runner
WHERE request_id = #{requestId}
  AND tool_call_id = #{toolCallId}
LIMIT 1
